class Bird {
  constructor(size, pos, vel) {
    this.size = size;
    this.pos = pos;
    this.vel = vel;
    this.acc = createVector();
    this.maxSpeed = random(2, 10);
    this.maxForce = 0.1;
  }
edges() {
if (this.pos.x < -this.size) this.pos.x = 600 + this.size;
if (this.pos.y < -this.size) this.pos.y = 600 + this.size;
if (this.pos.x > 600 + this.size) this.pos.x = -this.size;
if (this.pos.y > 600 + this.size) this.pos.y = -this.size;
}

align(birds) {
let perceptionRadius = 143;
let steering = createVector();
let total = 0;
for (let other of birds) {
let d = dist(this.pos.x, this.pos.y, other.pos.x, other.pos.y);
if (other != this && d < perceptionRadius) {
steering.add(other.vel);
total++;
}
}
if (total > 0) {
steering.div(total);
steering.setMag(this.maxSpeed);
steering.sub(this.vel);
steering.limit(this.maxForce);
}
return steering;
}

flock(birds) {
let alignment = this.align(birds);
this.acc.add(alignment);
this.edges();
}

show() {
  let chosen = chooseRandomColor();
 // stroke(chosen.colors[8]);
//  fill(1)
stroke(colorset3[1 % colorset3.length]);
strokeWeight(this.size);
  
stroke(0);
point(this.pos.x, this.pos.y);
 // circle(this.pos.x, this.pos.y,50);
}

update() {
this.vel.add(this.acc);
this.vel.limit(this.maxSpeed * (1 + 1.2 * __ot("fly"))); // پرواز پرنده‌های گله ← بلندی صدا
this.pos.add(this.vel);
this.acc.set(0, 0);
}
}

