let toRemove = null; // متغیر برای نگهداری شیپی که باید حذف شود
function mouseClicked() {
  if (toRemove == null) { // اگر شیپی برای حذف وجود ندارد، یک شیپ را به صورت تصادفی برای حذف انتخاب کن
    let options = ['ship1', 'ship2', 'ship3', 'ship4', 'ship5', 'ship6', 'ship7', 'ship8', 'ship9', 'ship10'];
    toRemove = random(options);
  } else { // در غیر اینصورت، شیپی که برای حذف انتخاب شده بود را حذف کن و متغیر حذف را صفر کن
    switch (toRemove) {
      case 'ship1':
        ship1();
        break;
      case 'ship2':
        ship2();
        break;
      case 'ship3':
        ship3();
        break;
      case 'ship4':
        ship4();
        break;
      case 'ship5':
        ship5();
        break;
      case 'ship6':
        ship6();
        break;
      case 'ship7':
        ship7();
        break;
      case 'ship8':
        ship8();
        break;
      case 'ship9':
        ship9();
        break;
      case 'ship10':
        ship10();
        break;
    }
    toRemove = null;
  }
}

