  function getDir(p = 0.1) {
    
    let r = hl.random(0, 1);
    let lp = 1 - p;
    let l = false;
    let ri = false;
    if (r >= lp) {
      l = true;
    } else if (r <= p) {
      ri = true;
    } else {
      l = true;
      ri = true;
    }
    return createVector(l, ri);
  }
  
  function drawosbranch(th, h, thres, ts, bp) {
    
    ts *= hl.random(0.6, 0.9);
    shapegraphic2.strokeWeight(ts);
    shapegraphic2.push();
    shapegraphic2.rotate(-th);
    shapegraphic2.line(0, 0, 0, -h);
    shapegraphic2.translate(0, -h);
  
    shapegraphic2.push(); // شاخه دوم
    shapegraphic2.rotate(radians(hl.random(20, 40)));
  
    shapegraphic2.pop();
  
    let v = getDir(hl.random(0.4, 0.6));
    let l = v.x;
    let r = v.y;
  
    osbranch(h, l, r, thres, ts, bp);
    shapegraphic2.pop();
  }
  function osbranch(h, l, r, thres = 6, ts = 3, bp = []) {
    
    let a = hl.random(-30, 30);
    let s = 6;
    let t = radians(a);
  
    h *= hl.random(0.7, 1);
  
    let i = bp.length;
    bp[i] = createVector(bp[i - 1].x + h * cos(t), bp[i - 1].y - h * sin(t));
  
    if (bp[i].x > 0 && bp[i].y > 0) {
      if (h > thres) {
        if (r) {
          drawosbranch(t, h, thres, ts, bp);
        }
        if (l) {
          drawosbranch(-t, h, thres, ts, bp);
        }
      } else {
       shapegraphic2.fill(randomColorx(Summer5));
       shapegraphic2.stroke(randomColorx(Summer5));
        shapegraphic2.strokeWeight(hl.random(0, 4));
       shapegraphic2.line(0, 0, hl.random(0, 20), hl.random(0, 50));
        shapegraphic2.translate(0, -h);
      }
    }
  }
  function multiosbranch(bs, l, r, ts = new Random().random_num(100, 600), nb = new Random().random_num(30, 200)) {
    
    for (let i = 0; i <= nb; i++) {
      const os = hl.random(20, 200);
      let bp = [];
      bp[0] = createVector(2000 / 2, 1000 - os);
      osbranch(bs, l, r, thres = hl.random(10, 20), ts = ts, bp);
    }
  }
  
