function get_direction_1(probability = 0.1) {
   let random_int = hl.random(0,1)
   let left_probability = 1 - probability
   let left = false;
     let right = false;
   if (hl.random_int >= left_probability) {
       left = true
       }
   else if (hl.random_int <= probability) {
       left = true
       }
   
       else {
           left = true
           right = true
             
       }
   return createVector(left, right)

}


function draw_branch_1(theta, h, threshold, first_thickness_size_1, branch_positions) {
 first_thickness_size_1 *= hl.random(0.6, 0.9);
      shapegraphic2.stroke(0);
 shapegraphic2.strokeWeight(first_thickness_size_1);
 shapegraphic2.push();
 shapegraphic2.rotate(-theta);
 shapegraphic2.line(0, 0, 0, -h);
 shapegraphic2.translate(0, -h);

 shapegraphic2.line(hl.random(0, 10000), hl.random(0, 10000), hl.random(0, 10000), hl.random(0, 10000));
 //shapegraphic2.line(hl.random(0, 10000), hl.random(0, 10000), hl.random(0, 10000), hl.random(0, 10000));
 //shapegraphic2.line(hl.random(0, 10000), hl.random(0, 10000), hl.random(0, 10000), hl.random(0, 10000));
 

 

 let vector = get_direction_1();
 let left = vector.x;
 let right = vector.y;

 branch_1(h, left, right, threshold, first_thickness_size_1, branch_positions);
 shapegraphic2.pop();
}


function branch_1(h, left, right, threshold = 6, first_thickness_size_1 = 3, branch_positions = []) {

 let a = hl.random(-30, 30)
 let steps = 6
 let theta = radians(a)


   
 h *= hl.random(0.7, 1);
   
   let i = branch_positions.length
   branch_positions[i] = createVector(branch_positions[i-1].x + h*cos((theta)), branch_positions[i-1].y - h*sin((theta)))
   //shapegraphic2.line(hl.random(0,10000), hl.random(0,10000), hl.random(0,10000), hl.random(0,10000))

   
   
   if (branch_positions[i].x > 0 && branch_positions[i].y > 0) {
   
 if (h > threshold) {
   if (right) {
       draw_branch_1(theta, h, threshold, first_thickness_size_1, branch_positions)  
   

       }
       if (left) {
     
         draw_branch_1(-theta, h, threshold, first_thickness_size_1, branch_positions)
      
   }
       }
 else {

     shapegraphic2.push()

  
     
   


    shapegraphic2.fill(randomColorx(Summer5));
    shapegraphic2.stroke(randomColorx(Summer5));
  shapegraphic2.strokeWeight(hl.random(0,4));
     shapegraphic2.line(0, 0, hl.random(0,20), hl.random(0,50))
 
     shapegraphic2.translate(0,-h)
   shapegraphic2.pop()

   }
   }
   
}

function randomColorx(Summer5) {
 return hl.randomElement(Summer5);
}

