function multiple_branch_1(first_branch_size_1, left, right, first_thickness_size_1 = hl.random(100,600), number_of_branches = hl.random(30,200)) {
   for (let i = 0; i <= number_of_branches; i++) {
       const original_size_1 = (20,200)
       let branch_positions = []
       branch_positions[0] = createVector(2000/2, (1000-original_size_1))
       branch_1(first_branch_size_1, left, right, threshold = hl.random(10,20), first_thickness_size_1 = first_thickness_size_1, branch_positions);

   }

       
}







function get_direction(probability = hl.random(0.1, 0.5)) {
 let random_int = hl.random(0, 1);
 let left_probability = 1 - probability;
 let left = false;
 let right = false;
 if (random_int >= left_probability) {
   left = true;
 } else if (random_int <= probability) {
   left = true;
 } else {
   left = true;
   right = true;
 }
 return createVector(left, right);
}


function draw_branch(theta, h, threshold, first_thickness_size, branch_positions) {
 first_thickness_size *= hl.random(0.6, 0.9);

 shapegraphic2.strokeWeight(first_thickness_size);
 shapegraphic2.push();

 shapegraphic2.rotate(-theta);
 shapegraphic2.line(0, 0, 0, -h);
 shapegraphic2.translate(0, -h);
shapegraphic2.stroke(0, 0, 0, hl.random(20, 180));

 shapegraphic2.line(hl.random(0, 10000), hl.random(0, 10000), hl.random(0, 1000), hl.random(0, 10000));

 let vector = get_direction(hl.random(0.1, 0.5));
 let left = vector.x;
 let right = vector.y;

 branch(h, left, right, threshold, first_thickness_size, branch_positions);
shapegraphic2.fill(255, 255, 255, hl.random(20, 350));
 shapegraphic2.pop();
}


function branch(h, left, right, threshold = 6, first_thickness_size = 6, branch_positions = []) {
 let a = hl.random(-5, 30);
 let steps = hl.random(1, 10);
 let theta = radians(a);

 h *= hl.random(0.7, 1);

 let i = branch_positions.length;
 branch_positions[i] = createVector(branch_positions[i - 1].x + h * cos((theta)), branch_positions[i - 1].y - h * sin((theta)));

 if (branch_positions[i].x > 0 && branch_positions[i].y > 0) {
   if (h > threshold) {
     let direction = get_direction(hl.random(0.1, 0.5));
     if (right && direction.y) {
       draw_branch(theta, h, threshold, first_thickness_size, branch_positions);
     }
     if (left && direction.x) {
       draw_branch(-theta, h, threshold, first_thickness_size, branch_positions);
     }
   } else {
     shapegraphic2.push();
     shapegraphic2.noStroke();
     shapegraphic2.pop();
   }
 }
}


function multiple_branch(first_branch_size, left, right, first_thickness_size = hl.random(100, 600), number_of_branches = hl.random(30, 200)) {
 for (let i = 0; i <= number_of_branches; i++) {
   const original_size = hl.random(20, 100);
   let branch_positions = [];
   branch_positions[0] = createVector(3000 / 2, (3000 - original_size));
   branch(first_branch_size, left, right, threshold = hl.random(10, 20), first_thickness_size = first_thickness_size, branch_positions);
 }
}


function get_direction(probability = hl.random(0.1, 0.6)) {
 let random_int = hl.random(0, 1);
 let left_probability = 1 - probability;
 let left = false;
 let right = false;
 if (random_int >= left_probability) {
   left = true;
 } else if (random_int <= probability) {
   left = true;
 } else {
   left = true;
   right = true;
 }
 return createVector(left, right);
}


function draw_branch(theta, h, threshold, first_thickness_size, branch_positions) {
 first_thickness_size *= hl.random(0.6, 0.9);
 shapegraphic2.strokeWeight(first_thickness_size);
 shapegraphic2.push();
 shapegraphic2.rotate(-theta);
 shapegraphic2.line(0, 0, 0, -h);
 shapegraphic2.translate(0, -h);
 
 let vector = get_direction();
 let left = vector.x;
 let right = vector.y;

 branch(h, left, right, threshold, first_thickness_size, branch_positions);
shapegraphic2.fill(255, 255, 255, hl.random(20, 350));
 shapegraphic2.pop();
}


function branch(h, left, right, threshold = 6, first_thickness_size = 6, branch_positions = []) {
 let a = hl.random(-15, 30);
 let steps = hl.random(1, 6);
 let theta = radians(a);

 h *= hl.random(0.7, 1);

 let i = branch_positions.length;
 branch_positions[i] = createVector(branch_positions[i-1].x + h*cos((theta)), branch_positions[i-1].y - h*sin((theta)));

 if (branch_positions[i].x > 0 && branch_positions[i].y > 0) {
   if (h > threshold) {
     if (right) {
       draw_branch(theta, h, threshold, first_thickness_size, branch_positions);  
     }
     if (left) {
       draw_branch(-theta, h, threshold, first_thickness_size, branch_positions);
     }
   } else {
     shapegraphic2.push();
     shapegraphic2.noStroke();
    shapegraphic2.fill(randomColorhk(colorset));
     //shapegraphic2.fill(color(random(colorset))); // تنظیم رنگ پر
     shapegraphic2.ellipse(0, 0, hl.random(1,4), hl.random(1,40));
     
    shapegraphic2.fill(color(255, 255, 255, hl.random(5, 20))); // تنظیم رنگ پر دایره دوم
     shapegraphic2.ellipse(0, 0, hl.random(1,10), hl.random(1,40));

    shapegraphic2.stroke(randomColorhk(colorset)); // تنظیم رنگ خط
     shapegraphic2.strokeWeight(hl.random(0.1, 0.6));

     shapegraphic2.arc(0,0, hl.random(5, 7), hl.random(35, 57), HALF_PI, PI);
     shapegraphic2.arc(0,0, hl.random(6, 7), hl.random(46, 57), HALF_PI, PI);
     shapegraphic2.arc(0,0, hl.random(7, 8), hl.random(57, 57), HALF_PI, PI);
     shapegraphic2.arc(0,0, hl.random(5, 7), hl.random(-35, -57), HALF_PI, PI);
     shapegraphic2.arc(0,0, hl.random(6, 7), hl.random(-46, -57), HALF_PI, PI);
     shapegraphic2.arc(0,0, hl.random(7, 8), hl.random(-57, -57), HALF_PI, PI);
     
     shapegraphic2.translate(0,-h);
     shapegraphic2.line(0, 0, 0, hl.random(10, 20)); // خط رسم کردن
     shapegraphic2.pop();
   }
 }
}


function randomColorhk(colorset) {
 return hl.randomElement(colorset);
}

