 function A4(randomNumber, color) {
  let rnd = new Random();
  shapegraphic2.noStroke();
  shapegraphic2.beginShape();
  shapegraphic2.curveVertex(windowWidth, windowHeight);
 
  for (let i = 0; i < PD.length - 1; i++) {
    const p1 = PD[i];
    const p2 = PD[i + 1];
 
    let x = map(noise(xoff5), 0, 1, 0, generateRandomNumber1(hl.random(randomNumber), rnd));
    let y = map(noise(yoff5), 0, 1, 0, generateRandomNumber1(hl.random(randomNumber), rnd));
 
   shapegraphic2.stroke(color);
    shapegraphic2.noFill();
    shapegraphic2.strokeWeight(hl.random(0.1, 0.9));
 
    shapegraphic2.arc(x + 5, y, 5, 2, PI - QUARTER_PI, -6 * TWO_PI);
   shapegraphic2.stroke(color);
    shapegraphic2.strokeWeight(hl.random(0.1, 0.9));
 
    shapegraphic2.arc(x + 5, y, 5, 2, PI - QUARTER_PI, -6 * TWO_PI);
   shapegraphic2.stroke(color);
    shapegraphic2.strokeWeight(hl.random(0.1, 0.9));
 
    shapegraphic2.arc(x, y, generateRandomNumber1(hl.random(randomNumber), rnd), generateRandomNumber1(hl.random(randomNumber), rnd) / 100, PI - QUARTER_PI, -6 * TWO_PI);
    xoff5 += 0.0001;
    yoff5 += 0.0001;
  }
  shapegraphic2.endShape();
  t++;
 }
 
 
 
 
