 function A2B() {
 
    if (treeCounterA2B >= numTreesA2B) {
  
      return;
  }
 
  const dim = Math.min(adasdim,adasdim);
 shapegraphic2.strokeWeight(dim * 0.015);
  const r = dim * 0.03;
  
    
 
 shapegraphic2.stroke(0)
 shapegraphic2.noFill()
 
 //shapegraphic2.scale(hl.random(0.2, 0.8));
 const A2Bos = dim * 0.03;
 shapegraphic2.translate(width/2,height/2)
 let A2Bbs = dim * 0.5;
 let A2Bv = getDir(0.5);
 let A2Bl = A2Bv.x;
 let A2Br = A2Bv.y;
 let A2Bts = width/20;
 let A2Bnb = hl.random(2, 4);
 shapegraphic2.strokeWeight(A2Bts);
 shapegraphic2.circle(0,  0, -A2Bos);
 shapegraphic2.translate(0, -A2Bos);
 multibranchA2B(A2Bbs, A2Bl, A2Br, A2Bts, A2Bnb);
 drawTreeA2B = false;
 
  treeCounterA2B++;
  drawTreeA2B = true;
  //shapegraphic2.scale(1.8);
 shapegraphic2.translate(-(width/2),-(height/2))
 
 }
 function getDir(A2Bp = 0.1) {
 let A2Br = hl.random(0, 1);
 let A2Blp = 1 - A2Bp;
 let A2Bl = false;
 let A2Bri = false;
 if (A2Br >= A2Blp) {
 A2Bl = true;
 } else if (A2Br <= A2Bp) {
 A2Bl = true;
 } else {
 A2Bl = true;
 A2Bri = true;
  
 }
 return createVector(A2Bl, A2Bri);
 }
 function drawbranchA2B(A2Bth, A2Bh, A2Bthres, A2Bts, A2Bbp) {
 A2Bts *= hl.random(0.6, 0.9);
 shapegraphic2.strokeWeight(A2Bts);
 shapegraphic2.push();
 shapegraphic2.rotate(-A2Bth);
 shapegraphic2.circle(0,  0, -A2Bh);
 shapegraphic2.translate(0, -A2Bh);
 shapegraphic2.push(); // شاخه دوم
 shapegraphic2.rotate(radians(30));
 const dim = Math.min(adasdim,adasdim);
 //shapegraphic2.strokeWeight(dim * 0.010);
 const r = dim * 6;
 let chosen = chooseRandomColor();
 shapegraphic2.stroke(chosen.colors[1]);
      // // تنظیم حالت مخلوط کردن برای رنگ‌ها
        shapegraphic2.line(hl.random(0,r), hl.random(0,r), hl.random(0,r), hl.random(0,r))
 
    //  shapegraphic2.noStroke();
     shapegraphic2.stroke(0);
   shapegraphic2.line(hl.random(0,r), hl.random(0,r), hl.random(0,r), hl.random(0,r))
 shapegraphic2.stroke(chosen.colors[20]);
   shapegraphic2.line(hl.random(0,r), hl.random(0,r), hl.random(0,r), hl.random(0,r))
 
 shapegraphic2.stroke(255);
   shapegraphic2.line(hl.random(0,r), hl.random(0,r), hl.random(0,r), hl.random(0,r))
 
 
 shapegraphic2.pop();
 let A2Bv = getDir();
 let A2Bl = A2Bv.x;
 let A2Br = A2Bv.y;
 branchA2B(A2Bh, A2Bl, A2Br, A2Bthres, A2Bts, A2Bbp);
 shapegraphic2.pop();
 }
 function branchA2B(A2Bh, A2Bl, A2Br, A2Bthres = 6, A2Bts = 3, A2Bbp = []) {
 let A2Ba = hl.random(-30, 30);
 let A2Bs = 6;
 let A2Bt = radians(A2Ba);
 A2Bh *= hl.random(0.7, 1);
 let A2Bi = A2Bbp.length;
 A2Bbp[A2Bi] = createVector(A2Bbp[A2Bi - 1].x + A2Bh * cos(A2Bt), A2Bbp[A2Bi - 1].y - A2Bh * sin(A2Bt));
 // 
  
 if (A2Bbp[A2Bi].x > 0 && A2Bbp[A2Bi].y > 0) {
 if (A2Bh > A2Bthres) {
 if (A2Br) {
 drawbranchA2B(A2Bt, A2Bh, A2Bthres, A2Bts, A2Bbp);
 
 }
 if (A2Bl) {
 drawbranchA2B(-A2Bt, A2Bh, A2Bthres, A2Bts, A2Bbp);
 
 }
 } else {
 
 shapegraphic2.fill(kijosk[1]);
       shapegraphic2.stroke(randomColorx(Summer5));
        shapegraphic2.strokeWeight(hl.random(0, 4));
       shapegraphic2.line(0, 0, hl.random(0, 20), hl.random(0, 50));
 shapegraphic2.translate(0, -A2Bh);
 
 }
 }
 }
 function multibranchA2B(A2Bbs, A2Bl, A2Br, A2Bts = hl.random(100, 600), A2Bnb = hl.random(30, 200)) {
 for (let i = 0; i <= A2Bnb; i++) {
 const A2Bos = (20, 200);
 let A2Bbp = [];
 A2Bbp[0] = createVector(2000 / 2, 1000 - A2Bos);
 branchA2B(A2Bbs, A2Bl, A2Br, A2Bthres = hl.random (10, 20), A2Bts = A2Bts, A2Bbp);
 
 }
 }
 
