    shapegraphic2.stroke(0, 0, 0, hl.random(1, 100));
    shapegraphic2.strokeWeight(hl.random(0.1, 0.9));
   shapegraphic2.fill(randomColoru3(colors26p));
  
  
    //shapegraphic2.ellipse(0, 0, random(30,30), random(-30,30))
    shapegraphic2.ellipse(10, 10, 6, 30);
  shapegraphic2.fill(255)
  shapegraphic2.circle(0,0,20)
  shapegraphic2.fill(randomColoru3(colors26p));
    shapegraphic2.ellipse(10, 20, 16, 60);
  shapegraphic2.fill(255)
  shapegraphic2.circle(0,0,20)
   shapegraphic2.fill(randomColoru3(colors26p));
    //shapegraphic2.ellipse(0, 0, random(30,30), random(-30,30))
