function SHK1() {
if (!KIJA2SHKTree) {
  return;
}
  
   let xoff = 0.0; 

//stroke(1,1,1,random(1,12))
  shapegraphic2.noStroke()
  let x2 = 800/A2('k')+A2('k');
  let y2 = 800/A2('k'+A2('k'));
  
  // جابجایی بیضی با وزش باد
  let wind = (map(noise(xoff), 0, 1, -1, 1)) * __vizWind();
  xoff += frequency*2;
  x2 += wind;
  
  //  fill(colorset3[3 % colorset3.length]); 

  
shapegraphic2.fill(255); 
  shapegraphic2.beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.1) {
    let xnoise = map(cos(angle), -1, 1, 0, 3);
    let ynoise = map(sin(angle), -1, 1, 0, 3);
    let distortion = map(noise(xoff + xnoise, yoff + ynoise), 0, 1, -amplitude, amplitude);
    let xr = (r2 + distortion) * cos(angle);
    let yr = (r2 + distortion) * sin(angle);
    vertex(x2 + xr*5, y2 + yr*5);
   // clear(x2 - r2 - amplitude, y2 - r2 - amplitude, r2 * 2 + amplitude * 2, r2 * 2 + amplitude * 2);
     //clear();
  }
  

  shapegraphic2.endShape(CLOSE);

 const dim = Math.max(800,800);
  shapegraphic2.strokeWeight(dim * 0.03);
 const r = dim * 0.3;




shapegraphic2.strokeWeight(dim * 0.00015);


stroke(0)


 
//shapegraphic2.scale(2.5)
const KIJA2os = dim * 0.003
shapegraphic2.translate((width/0.9), height*0.8 );
let KIJA2bs = dim * 0.299
let KIJA2v = getDirKIJA2(0.5);
let KIJA2l = KIJA2v.x;
let KIJA2r = KIJA2v.y;
let KIJA2ts = dim * 0.14
let KIJA2nb = hl.random(2, 4);
shapegraphic2.strokeWeight(KIJA2ts);
shapegraphic2.line(0, 0, 0, -KIJA2os);
shapegraphic2.translate(0, -KIJA2os);
multiBranchKIJA2(KIJA2bs, KIJA2l, KIJA2r, KIJA2ts, KIJA2nb);
KIJA2SHKTree = false;
}
function getDirKIJA2(KIJA2p = 0.1) {
let KIJA2r = hl.random(0, 1);
let KIJA2lp = 1 - KIJA2p;
let KIJA2l = false;
let KIJA2ri = false;
if (KIJA2r >= KIJA2lp) {
KIJA2l = true;
} else if (KIJA2r <= KIJA2p) {
KIJA2l = true;
} else {
KIJA2l = true;
KIJA2ri = true;
}
return createVector(KIJA2l, KIJA2ri);
}
function SHKBranchKIJA2(KIJA2th, KIJA2h, KIJA2thres, KIJA2ts, KIJA2bp) {
KIJA2ts *= 0.8;
shapegraphic2.strokeWeight(KIJA2ts);
shapegraphic2.push();
shapegraphic2.rotate(-KIJA2th);
shapegraphic2.line(0, 0, 0, -KIJA2h);
shapegraphic2.translate(0, -KIJA2h);

shapegraphic2.push(); // شاخه دوم
shapegraphic2.rotate(radians(30));

shapegraphic2.pop();
let KIJA2v = getDirKIJA2();
let KIJA2l = KIJA2v.x;
let KIJA2r = KIJA2v.y;
branchKIJA2(KIJA2h, KIJA2l, KIJA2r, KIJA2thres, KIJA2ts, KIJA2bp);
shapegraphic2.pop();
}
function branchKIJA2(KIJA2h, KIJA2l, KIJA2r, KIJA2thres = 6, KIJA2ts = 3, KIJA2bp = []) {
 
let KIJA2a = hl.random(-30, 0);
let KIJA2s = 6;
let KIJA2t = radians(KIJA2a);
KIJA2h *= hl.random(0.7, 1);
let KIJA2i = KIJA2bp.length;
KIJA2bp[KIJA2i] = createVector(KIJA2bp[KIJA2i - 1].x + KIJA2h * cos(KIJA2t), KIJA2bp[KIJA2i - 1].y - KIJA2h * sin(KIJA2t));
shapegraphic2.stroke(0)
if (KIJA2bp[KIJA2i].x > 0 && KIJA2bp[KIJA2i].y > 0) {
if (KIJA2h > KIJA2thres) {
if (KIJA2r) {
SHKBranchKIJA2(KIJA2t, KIJA2h, KIJA2thres, KIJA2ts, KIJA2bp);
}
if (KIJA2l) {
SHKBranchKIJA2(-KIJA2t, KIJA2h, KIJA2thres, KIJA2ts, KIJA2bp);
}
} else {
 

//const randomColorsT =hl.randomElement(ss3List);
//fill(randomColorsT);
//stroke(randomColorsT);
     let chosen = chooseRandomColor();

     // // تنظیم حالت مخلوط کردن برای رنگ‌ها
     
     noStroke();
    shapegraphic2.fill(chosen.colors[3]);


 noStroke();
 
  shapegraphic2.circle(0,0, hl.random(1,4));

     shapegraphic2.strokeWeight(hl.random(1.0,6));
//stroke(randomColorsT);

     noFill();
shapegraphic2.stroke(chosen.colors[4]);

shapegraphic2.strokeWeight(hl.random(0.1,0.6));
//stroke(random (red))
shapegraphic2.arc(0,0, 5,35, HALF_PI, PI);
shapegraphic2.arc(0,0, 6,46, HALF_PI, PI);
shapegraphic2.arc(0,0, 7,57, HALF_PI, PI);
shapegraphic2.arc(0,0, 5,-35, HALF_PI, PI);
shapegraphic2.arc(0,0, 6,-46, HALF_PI, PI);
shapegraphic2.arc(0,0, 7,-57, HALF_PI, PI);    
shapegraphic2.translate(0, -KIJA2h);


}
}
}
function multiBranchKIJA2(KIJA2bs, KIJA2l, KIJA2r, KIJA2ts = hl.random(10, 600), KIJA2nb = hl.random(10, 30)) {
for (let i = 0; i <= KIJA2nb; i++) {
const KIJA2os = hl.random(20, 200);
let KIJA2bp = [];
KIJA2bp[0] = createVector(2000 / 2, 1000 - KIJA2os);
branchKIJA2(KIJA2bs, KIJA2l, KIJA2r, KIJA2thres = hl.random(10, 20), KIJA2ts = KIJA2ts, KIJA2bp);
}
}
