function getDir(roip = 0.1) {
  let roir = random(0, 1);
  let roilp = 1 - roip;
  let roil = false;
  let roiri = false;
  if (roir >= roilp) {
    roil = true;
  } else if (roir <= roip) {
    roil = true;
  } else {
    roil = true;
    roiri = true;
  }
  return createVector(roil, roiri);
}

function drawBranchroi(roith, roih, roithres, roits, roibp) {
  roits *= random(0.6, 0.9);
  shapegraphic2.strokeWeight(roits);
  shapegraphic2.push();
  shapegraphic2.rotate(-roith);
  shapegraphic2.line(0, 0, 0, -roih);
  shapegraphic2.translate(0, -roih);
  shapegraphic2.push();
  shapegraphic2.rotate(radians(30));
  shapegraphic2.pop();
  let roiv = getDir();
  let roil = roiv.x;
  let roir = roiv.y;
  Branchroi(roih, roil, roir, roithres, roits, roibp);
  shapegraphic2.pop();
}

function Branchroi(roih, roil, roir, roithres = 6, roits = 3, roibp = []) {
  let roia = random(-30, 30);
  let rois = 6;
  let roit = radians(roia);
  roih *= random(0.7, 1);
  let roii = roibp.length;
  roibp[roii] = createVector(roibp[roii - 1].x + roih * cos(roit), roibp[roii - 1].y - roih * sin(roit));
  if (roibp[roii].x > 0 && roibp[roii].y > 0) {
    if (roih > roithres) {
      if (roir) {
        drawBranchroi(roit, roih, roithres, roits, roibp);
      }
      if (roil) {
        drawBranchroi(-roit, roih, roithres, roits, roibp);
      }
    } else {
      shapegraphic2.stroke(120);
      shapegraphic2.strokeWeight(random(0, 4));
      shapegraphic2.line(0, 0, random(0, 20), random(0, 50));
      shapegraphic2.translate(0, -roih);
    }
  }
}

function multiBranchroi(roibs, roil, roir, roits = random(100, 600), roinb = random(30, 200)) {
  for (let i = 0; i <= roinb; i++) {
    const roios = (20, 200);
    let roibp = [];
    roibp[0] = createVector(2000 / 2, 1000 - roios);
    Branchroi(roibs, roil, roir, roithres = hl.random(10, 20), roits = roits, roibp);
  }
}
