 function get_ghabsh12_direction_1(probabilighab = 0.1) {
 let random_int = hl.random(0,1)
 let left_ghabsh12_probabilighab = 1 - probabilighab
 let left_ghabsh12 = false;
  let right_ghabsh12 = false;
 if (random_int >= left_ghabsh12_probabilighab) {
    left_ghabsh12 = true
    }
 else if (random_int <= probabilighab) {
    left_ghabsh12 = true
    }
 
    else {
        left_ghabsh12 = true
        right_ghabsh12 = true
          
    }
 return createVector(left_ghabsh12, right_ghabsh12)
 
 }
 
