 function branch_ghabsh12_1(h, left_ghabsh12, right_ghabsh12, threshold = 6, first_thickness_ghabsh12_size_1 = 3, branch_ghabsh12_positions = []) {
 
 let a = hl.random(-30, 30)
 let steps = 6
 let theta = radians(a)
 
 
 
 h *= hl.random(0.7, 1);
 
 let i = branch_ghabsh12_positions.length
 branch_ghabsh12_positions[i] = createVector(branch_ghabsh12_positions[i-1].x + h*cos((theta)), branch_ghabsh12_positions[i-1].y - h*sin((theta)))
 //shapegraphic2.line(random(0,10000), random(0,10000), random(0,10000), random(0,10000))
 
 
 
 if (branch_ghabsh12_positions[i].x > 0 && branch_ghabsh12_positions[i].y > 0) {
 
 if (h > threshold) {
 if (right_ghabsh12) {
    draw_branch_ghabsh12_1(theta, h, threshold, first_thickness_ghabsh12_size_1, branch_ghabsh12_positions)  
        //# Whenever we get_ghabsh12 back here, we "_ghabsh12" in order to restore the previous matrix state
 
    }
    if (left_ghabsh12) {
  
      draw_branch_ghabsh12_1(-theta, h, threshold, first_thickness_ghabsh12_size_1, branch_ghabsh12_positions)
     //shapegraphic2.stroke(random (Summer5))
     // shapegraphic2.line(random(0,10000), random(0,10000), random(0,50), random(0,10))
 //shapegraphic2.noStroke();
      // Repeat the same thing, only branch_ghabsh12 off to the "left_ghabsh12" this time!
 }
    }
 else {
 
  shapegraphic2.push()
 
 shapegraphic2.stroke(0, 0, 0, hl.random(1, 100));
  shapegraphic2.strokeWeight(hl.random(0.1, 0.9));
 shapegraphic2.fill(randomColoru(Atumn));
 
 
  //shapegraphic2.ellipse(0, 0, random(30,30), random(-30,30))
  shapegraphic2.ellipse(10, 10, 3, 15);
  shapegraphic2.ellipse(10, 20, 8, 30);
 shapegraphic2.fill(randomColoru(Atumn));
  //shapegraphic2.ellipse(0, 0, random(30,30), random(-30,30))
  shapegraphic2.ellipse(10, 35, 2, 10);
  shapegraphic2.ellipse(10, 45, 2, 15);
  shapegraphic2.translate(0, -h);
  shapegraphic2.translate(0,-h)
shapegraphic2.pop()
      //
 
 }
 }
 
 }
 
