class Grass18 {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.angle = 0;  // زاویه برای حرکت علف با باد
  }
  
  show() {
    noStroke();
    //fill(100, 200, 100);
    fill(0)
    fill(255)
    fill(colorset[4 % colorset.length]);
    fill("#FDCD00")
    ellipse(this.x, this.y, this.size/random(1,2), this.size*random(3,5));
  
    noFill()
  }
  
  move() {
    this.angle += 0.05;  // افزایش زاویه برای حرکت علف با باد
    this.y += sin(this.angle) / 2;  // حرکت علف به سمت پایین با باد
    if (this.y > height + this.size) {
      this.y = -this.size;  // بازگشت علف به بالای صفحه
    }
  }
}
