function drawm1() {
  noFill();
  const colors = ['#E55A2E', '#E5BC4B', '#FEED61', '#DAEC5E', '#3F864D', '#58B2B0', '#5B8FEB', '#3260B2', '#000000'];
  const shape = [];
  for (let i = -10; i < 3; i++) {
    let y = i * (400);
    shape.push(createVector(0, y));
  }

  for (let i = 0; i < 1000 / 2; i++) {
    stroke(255, 100);
    strokeWeight(0.6);
    beginShape();
    curveVertex(shape[0].x, shape[0].y); // Connect the starting point
    for (let j = 0; j < shape.length; j++) {
      const vector = shape[j];
      curveVertex(vector.x, vector.y);
      const shift_y = 5;
      const drops_x = 5;
      vector.add(createVector(drops_x, shift_y));
    }
    curveVertex(shape[shape.length - 1].x, shape[shape.length - 1].y); // Connect the ending point
    endShape();

    stroke(120);
    strokeWeight(0.2);
    beginShape();
    curveVertex(shape[0].x, shape[0].y); // Connect the starting point
    for (let j = 0; j < shape.length; j++) {
      const vector = shape[j];
      curveVertex(vector.x, vector.y);
      const shift_y = 5;
      const drops_x = 2;
      vector.add(createVector(drops_x, shift_y));
    }
    curveVertex(shape[shape.length - 1].x, shape[shape.length - 1].y); // Connect the ending point
    endShape();
  }
}


